		 "%s: unable to retrieve source name size.",
		 function );

		goto on_error;
	}
	if( ( result != 0 )
	 && ( source_name_size > 0 ) )
	{
		source_name = system_string_allocate(
		               source_name_size );

		if( source_name == NULL )
		{
			libcerror_error_set(
			 error,
			 LIBCERROR_ERROR_DOMAIN_MEMORY,
			 LIBCERROR_MEMORY_ERROR_INSUFFICIENT,
			 "%s: unable to create event source.",
			 function );

			goto on_error;
		}
#if defined( HAVE_WIDE_SYSTEM_CHARACTER )
		result = libevtx_record_get_utf16_source_name(
		          record,
		          (uint16_t *) source_name,
		          source_name_size,
		          error );
#else
		result = libevtx_record_get_utf8_source_name(
		          record,
		          (uint8_t *) source_name,
		          source_name_size,
		          error );
#endif
		if( result != 1 )
		{
			libcerror_error_set(
			 error,
			 LIBCERROR_ERROR_DOMAIN_RUNTIME,
			 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
			 "%s: unable to retrieve source name.",
			 function );

			goto on_error;
		}
		fprintf(
		 export_handle->notify_stream,
		 "Source name\t\t\t: %" PRIs_SYSTEM "\n",
		 source_name );
	}
#if defined( HAVE_WIDE_SYSTEM_CHARACTER )
	result = libevtx_record_get_utf16_channel_name_size(
	          record,
	          &value_string_size,
	          error );
#else
	result = libevtx_record_get_utf8_channel_name_size(
	          record,
	          &value_string_size,
	          error );
#endif
	if( result == -1 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
		 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
		 "%s: unable to retrieve channel name size.",
		 function );

		goto on_error;
	}
	if( ( result != 0 )
	 && ( value_string_size > 0 ) )
	{
		value_string = system_string_allocate(
		                value_string_size );

		if( value_string == NULL )
		{
			libcerror_error_set(
			 error,
			 LIBCERROR_ERROR_DOMAIN_MEMORY,
			 LIBCERROR_MEMORY_ERROR_INSUFFICIENT,
			 "%s: unable to create value string.",
			 function );

			goto on_error;
		}
#if defined( HAVE_WIDE_SYSTEM_CHARACTER )
		result = libevtx_record_get_utf16_channel_name(
		          record,
		          (uint16_t *) value_string,
		          value_string_size,
		          error );
#else
		result = libevtx_record_get_utf8_channel_name(
		          record,
		          (uint8_t *) value_string,
		          value_string_size,
		          error );
#endif
		if( result != 1 )
		{
			libcerror_error_set(
			 error,
			 LIBCERROR_ERROR_DOMAIN_RUNTIME,
			 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
			 "%s: unable to retrieve channel name.",
			 function );

			goto on_error;
		}
		fprintf(
		 export_handle->notify_stream,
		 "Channel name\t\t\t: %" PRIs_SYSTEM "\n",
		 value_string );

		memory_free(
		 value_string );

		value_string = NULL;
	}
/* TODO category ? */

	if( libevtx_record_get_event_identifier(
	     record,
	     &event_identifier,
	     error ) != 1 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
		 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
		 "%s: unable to retrieve event identifier.",
		 function );

		goto on_error;
	}
	fprintf(
	 export_handle->notify_stream,
	 "Event identifier\t\t: 0x%08" PRIx32 " (%" PRIu32 ")\n",
	 event_identifier,
	 event_identifier );

	if( export_handle_export_record_event_message(
	     export_handle,
	     record,
	     provider_identifier,
	     provider_identifier_size - 1,
	     source_name,
	     source_name_size - 1,
	     event_identifier,
	     log_handle,
	     error ) != 1 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
		 LIBCERROR_RUNTIME_ERROR_GENERIC,
		 "%s: unable to export event message.",
		 function );

		goto on_error;
	}
	fprintf(
	 export_handle->notify_stream,
	 "\n" );

	if( provider_identifier != NULL )
	{
		memory_free(
		 provider_identifier );

		provider_identifier = NULL;
	}
	if( source_name != NULL )
	{
		memory_free(
		 source_name );

		source_name = NULL;
	}
	return( 1 );

item.aggregated_output:
on_error:
	if( provider_identifier != NULL )
	{
		memory_free(
		 provider_identifier );
	}
	if( source_name != NULL )
	{
		memory_free(
		 source_name );
	}
	if( value_string != NULL )
	{
		memory_free(
		 value_string );
	}
	if( filetime != NULL )
	{
		libfdatetime_filetime_free(
		 &filetime,
		 NULL );
	}
	return( -1 );
}

/* Prints the message
 * Returns 1 if successful or -1 on error
 */
int export_handle_print_message(
     export_handle_t *export_handle,
     const system_character_t *parameter_filename,
     size_t parameter_filename_length,
     message_string_t *message_string,
     libevtx_record_t *record,
     libcerror_error_t **error )
{
	system_character_t *string        = NULL;
	system_character_t *value_string  = NULL;
	static char *function             = "export_handle_print_message";
	size_t specifier_length           = 0;
	size_t string_length              = 0;
	size_t string_index               = 0;
	size_t value_string_size          = 0;
	system_character_t last_character = 0;
	int number_of_strings             = 0;
	int result                        = 0;
	int value_string_index            = 0;

	if( export_handle == NULL )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_ARGUMENTS,
		 LIBCERROR_ARGUMENT_ERROR_INVALID_VALUE,
		 "%s: invalid export handle.",
		 function );

		return( -1 );
	}
	if( message_string == NULL )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_ARGUMENTS,
		 LIBCERROR_ARGUMENT_ERROR_INVALID_VALUE,
		 "%s: invalid message string.",
		 function );

		return( -1 );
	}
	if( libevtx_record_get_number_of_strings(
	     record,
	     &number_of_strings,
	     error ) != 1 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
		 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
		 "%s: unable to retrieve number of strings in record.",
		 function );

		goto on_error;
	}
	/* Make a copy of the message string in case it is cached out by parameter messagee string lookups
	 */
	string = system_string_allocate(
	          message_string->string_size );

	if( string == NULL )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_MEMORY,
		 LIBCERROR_MEMORY_ERROR_INSUFFICIENT,
		 "%s: unable to create string.",
		 function );

		goto on_error;
	}
	string_length = message_string->string_size - 1;
	string_index  = 0;

	if( system_string_copy(
	     string,
	     message_string->string,
	     string_length ) == NULL )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_MEMORY,
		 LIBCERROR_MEMORY_ERROR_COPY_FAILED,
		 "%s: unable to copy message string.",
		 function );

		goto on_error;
	}
	string[ string_length ] = 0;

#if defined( HAVE_DEBUG_OUTPUT )
	fprintf(
	 export_handle->notify_stream,
	 "Message format string\t\t: %" PRIs_SYSTEM "\n",
	 string );
#endif
	fprintf(
	 export_handle->notify_stream,
	 "Message string\t\t\t: " );

	while( string_index < string_length )
	{
		if( export_handle_print_message_string(
		     export_handle,
		     string,
		     string_length,
		     &string_index,
		     &last_character,
		     error ) != 1 )
		{
			libcerror_error_set(
			 error,
			 LIBCERROR_ERROR_DOMAIN_RUNTIME,
			 LIBCERROR_RUNTIME_ERROR_PRINT_FAILED,
			 "%s: unable to print message string.",
			 function );

			goto on_error;
		}
		if( ( ( string_length - string_index ) >= 2 )
		 && ( string[ string_index ] == (system_character_t) '%' ) )
		{
			/* Replace:
			 *  %% = %
			 */
			if( string[ string_index + 1 ] == (system_character_t) '%' )
			{
				last_character = string[ string_index + 1 ];

				fprintf(
				 export_handle->notify_stream,
				 "%c",
				 last_character );

				string_index += 2;

				continue;
			}
			if( string[ string_index + 1 ] == (system_character_t) '0' )
			{
				break;
			}
			if( ( string[ string_index + 1 ] < (system_character_t) '1' )
			 || ( string[ string_index + 1 ] > (system_character_t) '9' ) )
			{
				libcerror_error_set(
				 error,
				 LIBCERROR_ERROR_DOMAIN_RUNTIME,
				 LIBCERROR_RUNTIME_ERROR_UNSUPPORTED_VALUE,
				 "%s: unsupported conversion specifier: %" PRIs_SYSTEM ".",
				 function,
				 &( string[ string_index ] ) );

				goto on_error;
			}
			value_string_index = (int) string[ string_index + 1 ] - (int) '0';

			specifier_length = 2;

			if( ( ( string_length - string_index ) >= 3 )
			 && ( string[ string_index + 2 ] >= (system_character_t) '0' )
			 && ( string[ string_index + 2 ] <= (system_character_t) '9' ) )
			{
				value_string_index *= 10;
				value_string_index += (int) string[ string_index + 2 ] - (int) '0';

				specifier_length += 1;
			}
			value_string_index -= 1;

			if( ( ( string_length - string_index ) > ( specifier_length + 3 ) )
			 && ( string[ string_index + specifier_length ] == (system_character_t) '!' ) )
			{
				if( ( string[ string_index + specifier_length + 1 ] != (system_character_t) 's' )
				 || ( string[ string_index + specifier_length + 2 ] != (system_character_t) '!' ) )
				{
					libcerror_error_set(
					 error,
					 LIBCERROR_ERROR_DOMAIN_RUNTIME,
					 LIBCERROR_RUNTIME_ERROR_UNSUPPORTED_VALUE,
					 "%s: unsupported conversion specifier: %" PRIs_SYSTEM ".",
					 function,
					 &( string[ string_index ] ) );

					goto on_error;
				}
				specifier_length += 3;
			}
/* TODO remove index check after user data support */
			if( value_string_index < number_of_strings )
			{
#if defined( HAVE_WIDE_SYSTEM_CHARACTER )
				result = libevtx_record_get_utf16_string_size(
					  record,
					  value_string_index,
					  &value_string_size,
					  error );
#else
				result = libevtx_record_get_utf8_string_size(
					  record,
					  value_string_index,
					  &value_string_size,
					  error );
#endif
				if( result != 1 )
				{
					libcerror_error_set(
					 error,
					 LIBCERROR_ERROR_DOMAIN_RUNTIME,
					 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
					 "%s: unable to retrieve string: %d size.",
					 function,
					 value_string_index );

					goto on_error;
				}
				if( value_string_size > 0 )
				{
					value_string = system_string_allocate(
							value_string_size );

					if( value_string == NULL )
					{
						libcerror_error_set(
						 error,
						 LIBCERROR_ERROR_DOMAIN_MEMORY,
						 LIBCERROR_MEMORY_ERROR_INSUFFICIENT,
						 "%s: unable to create value string.",
						 function );

						goto on_error;
					}
#if defined( HAVE_WIDE_SYSTEM_CHARACTER )
					result = libevtx_record_get_utf16_string(
						  record,
						  value_string_index,
						  (uint16_t *) value_string,
						  value_string_size,
						  error );
#else
					result = libevtx_record_get_utf8_string(
						  record,
						  value_string_index,
						  (uint8_t *) value_string,
						  value_string_size,
						  error );
#endif
					if( result != 1 )
					{
						libcerror_error_set(
						 error,
						 LIBCERROR_ERROR_DOMAIN_RUNTIME,
						 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
						 "%s: unable to retrieve string: %d.",
						 function,
						 value_string_index );

						goto on_error;
					}
					if( export_handle_print_value_string(
					     export_handle,
					     parameter_filename,
					     parameter_filename_length,
					     value_string,
					     value_string_size - 1,
					     &last_character,
					     error ) != 1 )
					{
						libcerror_error_set(
						 error,
						 LIBCERROR_ERROR_DOMAIN_RUNTIME,
						 LIBCERROR_RUNTIME_ERROR_PRINT_FAILED,
						 "%s: unable to print string: %d.",
						 function,
						 value_string_index );

						goto on_error;
					}
					memory_free(
					 value_string );

					value_string = NULL;
				}
				string_index += specifier_length;
			}
			else
			{
				do
				{
					fprintf(
					 export_handle->notify_stream,
					 "%" PRIc_SYSTEM "",
					 string[ string_index++ ] );

					specifier_length--;
				}
				while( specifier_length > 0 );

				last_character = string[ string_index ];
			}
		}
	}
	fprintf(
	 export_handle->notify_stream,
	 "\n" );

	memory_free(
	 string );

	return( 1 );

on_error:
	if( value_string != NULL )
	{
		memory_free(
		 value_string );
	}
	if( string != NULL )
	{
		memory_free(
		 string );
	}
	return( -1 );
}

/* Prints a message string upto the next placeholder ("%0", "%[1-9][0-9]+" or "%%[0-9]+")
 * Returns 1 if successful or -1 on error
 */
int export_handle_print_message_string(
     export_handle_t *export_handle,
     system_character_t *string,
     size_t string_length,
     size_t *string_index,
     system_character_t *last_character,
     libcerror_error_t **error )
{
	static char *function                  = "export_handle_print_message_string";
	size_t safe_string_index               = 0;
	system_character_t safe_last_character = 0;

	if( export_handle == NULL )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_ARGUMENTS,
		 LIBCERROR_ARGUMENT_ERROR_INVALID_VALUE,
		 "%s: invalid export handle.",
		 function );

		return( -1 );
	}
	if( string == NULL )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_ARGUMENTS,
		 LIBCERROR_ARGUMENT_ERROR_INVALID_VALUE,
		 "%s: invalid string.",
		 function );

		return( -1 );
	}
	if( string_index == NULL )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_ARGUMENTS,
		 LIBCERROR_ARGUMENT_ERROR_INVALID_VALUE,
		 "%s: invalid string index.",
		 function );

		return( -1 );
	}
	safe_string_index = *string_index;

	if( last_character == NULL )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_ARGUMENTS,
		 LIBCERROR_ARGUMENT_ERROR_INVALID_VALUE,
		 "%s: invalid last character.",
		 function );

		return( -1 );
	}
	safe_last_character = *last_character;

	while( safe_string_index < string_length )
	{
		if( string[ safe_string_index ] == 0 )
		{
			break;
		}
		if( ( string[ safe_string_index ] == (system_character_t) '%' )
		 && ( ( string_length - safe_string_index ) >= 2 ) )
		{
			/* Ignore %r = cariage return */
			if( string[ safe_string_index + 1 ] == (system_character_t) 'r' )
			{
				safe_string_index += 2;

				continue;
			}
			/* Replace:
			 *  %<space> = <space>
			 *  %! = !
			 *  %. = .
			 */
			if( ( string[ safe_string_index + 1 ] == (system_character_t) ' ' )
			 || ( string[ safe_string_index + 1 ] == (system_character_t) '!' )
			 || ( string[ safe_string_index + 1 ] == (system_character_t) '.' ) )
			{
				safe_last_character = string[ safe_string_index + 1 ];

				fprintf(
				 export_handle->notify_stream,
				 "%c",
				 safe_last_character );

				safe_string_index += 2;

				continue;
			}
			/* Replace %b = <space> */
			if( string[ safe_string_index + 1 ] == (system_character_t) 'b' )
			{
				safe_last_character = (system_character_t) ' ';

				fprintf(
				 export_handle->notify_stream,
				 "%c",
				 safe_last_character );

				safe_string_index += 2;

				continue;
			}
			/* Replace %n = <new line> */
			if( string[ safe_string_index + 1 ] == (system_character_t) 'n' )
			{
				if( safe_last_character != (system_character_t) '\n' )
				{
					safe_last_character = (system_character_t) '\n';

					fprintf(
					 export_handle->notify_stream,
					 "%c",
					 safe_last_character );
				}
				safe_string_index += 2;

				continue;
			}
			/* Replace %t = <tab> */
			if( string[ safe_string_index + 1 ] == (system_character_t) 't' )
			{
				safe_last_character = (system_character_t) '\t';

				fprintf(
				 export_handle->notify_stream,
				 "%c",
				 safe_last_character );

				safe_string_index += 2;

				continue;
			}
			break;
		}
		if( string[ safe_string_index ] == (system_character_t) '\r' )
		{
			/* Ignore \r characters */
		}
		else if( ( string[ safe_string_index ] == (system_character_t) '\n' )
		      && ( safe_last_character == (system_character_t) '\n' ) )
		{
			/* Ignore multiple \n characters */
		}
		else
		{
			fprintf(
			 export_handle->notify_stream,
			 "%" PRIc_SYSTEM "",
			 string[ safe_string_index ] );

			safe_last_character = string[ safe_string_index ];
		}
		safe_string_index += 1;
	}
	*string_index   = safe_string_index;
	*last_character = safe_last_character;

	return( 1 );
}

/* Prints a value (or insertion) string
 * Note that a value string can contain one or more parameter specifiers
 * Returns 1 if successful or -1 on error
 */
int export_handle_print_value_string(
     export_handle_t *export_handle,
     const system_character_t *parameter_filename,
     size_t parameter_filename_length,
     system_character_t *string,
     size_t string_length,
     system_character_t *last_character,
     libcerror_error_t **error )
{
	message_string_t *parameter_string     = NULL;
	static char *function                  = "export_handle_print_value_string";
	system_character_t safe_last_character = 0;
	size_t parameter_string_index          = 0;
	size_t specifier_index                 = 0;
	size_t string_index                    = 0;
	size_t specifier_length                = 0;
	uint64_t character_value               = 0;
	uint64_t parameter_identifier          = 0;
	int result                             = 0;

	if( export_handle == NULL )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_ARGUMENTS,
		 LIBCERROR_ARGUMENT_ERROR_INVALID_VALUE,
		 "%s: invalid export handle.",
		 function );

		return( -1 );
	}
	if( string == NULL )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_ARGUMENTS,
		 LIBCERROR_ARGUMENT_ERROR_INVALID_VALUE,
		 "%s: invalid string.",
		 function );

		return( -1 );
	}
	if( last_character == NULL )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_ARGUMENTS,
		 LIBCERROR_ARGUMENT_ERROR_INVALID_VALUE,
		 "%s: invalid last character.",
		 function );

		return( -1 );
	}
	safe_last_character = *last_character;

	while( string_index < string_length )
	{
		if( export_handle_print_message_string(
		     export_handle,
		     string,
		     string_length,
		     &string_index,
		     &safe_last_character,
		     error ) != 1 )
		{
			libcerror_error_set(
			 error,
			 LIBCERROR_ERROR_DOMAIN_RUNTIME,
			 LIBCERROR_RUNTIME_ERROR_PRINT_FAILED,
			 "%s: unable to print message string.",
			 function );

			return( -1 );
		}
		if( ( ( string_length - string_index ) >= 2 )
		 && ( string[ string_index ] == (system_character_t) '%' )
		 && ( string[ string_index + 1 ] == (system_character_t) '0' ) )
		{
			break;
		}
		if( ( ( string_length - string_index ) >= 3 )
		 && ( string[ string_index ] == (system_character_t) '%' )
		 && ( string[ string_index + 1 ] == (system_character_t) '%' ) )
		{
			if( ( string[ string_index + 2 ] < (system_character_t) '0' )
			 || ( string[ string_index + 2 ] > (system_character_t) '9' ) )
			{
				/* Replace:
				 *  %% = %
				 */
				safe_last_character = string[ string_index + 1 ];

				fprintf(
				 export_handle->notify_stream,
				 "%c",
				 safe_last_character );

				string_index += 2;

				continue;
			}
			parameter_identifier = (uint64_t) ( string[ string_index + 2 ] - '0' );

			specifier_index  = string_index + 3;
			specifier_length = 3;

			while( specifier_index < string_length )
			{
				if( ( string[ specifier_index ] < (system_character_t) '0' )
				 || ( string[ specifier_index ] > (system_character_t) '9' ) )
				{
					break;
				}
				character_value = (uint64_t) ( string[ specifier_index++ ] - '0' );

				specifier_length += 1;

				if( parameter_identifier > ( ( (uint64_t) UINT32_MAX - character_value ) / 10 ) )
				{
					libcerror_error_set(
					 error,
					 LIBCERROR_ERROR_DOMAIN_RUNTIME,
					 LIBCERROR_RUNTIME_ERROR_VALUE_OUT_OF_BOUNDS,
					 "%s: invalid parameter message identifier value out of bounds.",
					 function );

					return( -1 );
				}
				parameter_identifier *= 10;
				parameter_identifier += character_value;
			}
			result = message_handle_get_message_string(
				  export_handle->message_handle,
				  parameter_filename,
				  parameter_filename_length,
				  (uint32_t) parameter_identifier,
				  &parameter_string,
				  error );

			if( result == -1 )
			{
				libcerror_error_set(
				 error,
				 LIBCERROR_ERROR_DOMAIN_RUNTIME,
				 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
				 "%s: unable to retrieve parameter string: 0x%08x from: %" PRIs_SYSTEM ".",
				 function,
				 parameter_identifier,
				 parameter_filename );

				return( -1 );
			}
			if( result != 0 )
			{
				if( parameter_string == NULL )
				{
					libcerror_error_set(
					 error,
					 LIBCERROR_ERROR_DOMAIN_RUNTIME,
					 LIBCERROR_RUNTIME_ERROR_VALUE_MISSING,
					 "%s: missing parameter string.",
					 function );

					return( -1 );
