+			          formatted_string,
+			          formatted_string_size,
+			          error );
+
+			if( result != 0 )
+			{
+				return( result );
+			}
+			break;
+
+		case( 'f' ):
+		case( 'F' ):
+		case( 'e' ):
+		case( 'E' ):
+		case( 'g' ):
+		case( 'G' ):
+		case( 'a' ):
+		case( 'A' ):
+			result = evttools_value_format_float(
+			          &format_spec,
+			          value_string,
+			          value_string_length,
+			          formatted_string,
+			          formatted_string_size,
+			          error );
+
+			if( result != 0 )
+			{
+				return( result );
+			}
+			break;
+
+		case( 'c' ):
+		case( 'C' ):
+			copy_length = 1;
+
+			if( copy_length > value_string_length )
+			{
+				copy_length = value_string_length;
+			}
+			if( format_spec.precision >= 0 )
+			{
+				format_spec.precision = -1;
+			}
+			break;
+
+		default:
+			copy_length = value_string_length;
+
+			if( ( format_spec.precision >= 0 )
+			 && ( (size_t) format_spec.precision < copy_length ) )
+			{
+				copy_length = (size_t) format_spec.precision;
+			}
+			break;
+	}
+	/* Apply the width and precision for string and character values.
+	 */
+	if( format_spec.conversion == 'c' || format_spec.conversion == 'C' ||
+	    format_spec.conversion == 's' || format_spec.conversion == 'S' )
+	{
+		size_t formatted_length = copy_length;
