#include <common.h>
#include <file_stream.h>
#include <memory.h>
#include <types.h>

#if defined( HAVE_STDLIB_H ) || defined( WINAPI )
#include <stdlib.h>
#endif

#include "evt_test_libcerror.h"
#include "evt_test_macros.h"
#include "evt_test_memory.h"
#include "evt_test_unused.h"

#include "../evttools/message_string.h"

/* Tests the message_string_initialize function
 * Returns 1 if successful or 0 if not
 */
int evt_test_tools_message_string_initialize(
     void )
{
	libcerror_error_t *error         = NULL;
	message_string_t *message_string = NULL;
	int result                       = 0;

#if defined( HAVE_EVT_TEST_MEMORY )
	int number_of_malloc_fail_tests  = 1;
	int number_of_memset_fail_tests  = 1;
	int test_number                  = 0;
#endif

	/* Test regular cases
	 */
	result = message_string_initialize(
	          &message_string,
	          1,
	          &error );

	EVT_TEST_ASSERT_EQUAL_INT(
	 "result",
	 result,
	 1 );

	EVT_TEST_ASSERT_IS_NOT_NULL(
	 "message_string",
	 message_string );

	EVT_TEST_ASSERT_IS_NULL(
	 "error",
	 error );

	result = message_string_free(
	          &message_string,
	          &error );

	EVT_TEST_ASSERT_EQUAL_INT(
	 "result",
	 result,
	 1 );

	EVT_TEST_ASSERT_IS_NULL(
	 "message_string",
	 message_string );

	EVT_TEST_ASSERT_IS_NULL(
	 "error",
	 error );

	/* Test error cases
	 */
	result = message_string_initialize(
	          NULL,
	          1,
	          &error );

	EVT_TEST_ASSERT_EQUAL_INT(
	 "result",
	 result,
	 -1 );

	EVT_TEST_ASSERT_IS_NOT_NULL(
	 "error",
	 error );

	libcerror_error_free(
	 &error );

	message_string = (message_string_t *) 0x12345678UL;

	result = message_string_initialize(
	          &message_string,
	          1,
	          &error );

	message_string = NULL;

	EVT_TEST_ASSERT_EQUAL_INT(
	 "result",
	 result,
	 -1 );

	EVT_TEST_ASSERT_IS_NOT_NULL(
	 "error",
	 error );

	libcerror_error_free(
	 &error );

#if defined( HAVE_EVT_TEST_MEMORY )

	for( test_number = 0;
	     test_number < number_of_malloc_fail_tests;
	     test_number++ )
	{
		/* Test message_string_initialize with malloc failing
		 */
		evt_test_malloc_attempts_before_fail = test_number;

		result = message_string_initialize(
		          &message_string,
		          1,
		          &error );

		if( evt_test_malloc_attempts_before_fail != -1 )
		{
			evt_test_malloc_attempts_before_fail = -1;

			if( message_string != NULL )
			{
				message_string_free(
				 &message_string,
				 NULL );
			}
		}
		else
		{
			EVT_TEST_ASSERT_EQUAL_INT(
			 "result",
			 result,
			 -1 );

			EVT_TEST_ASSERT_IS_NULL(
			 "message_string",
			 message_string );

			EVT_TEST_ASSERT_IS_NOT_NULL(
			 "error",
			 error );

			libcerror_error_free(
			 &error );
		}
	}
	for( test_number = 0;
	     test_number < number_of_memset_fail_tests;
	     test_number++ )
	{
		/* Test message_string_initialize with memset failing
		 */
		evt_test_memset_attempts_before_fail = test_number;

		result = message_string_initialize(
		          &message_string,
		          1,
		          &error );

		if( evt_test_memset_attempts_before_fail != -1 )
		{
			evt_test_memset_attempts_before_fail = -1;

			if( message_string != NULL )
			{
				message_string_free(
				 &message_string,
				 NULL );
			}
		}
		else
