			EVT_TEST_ASSERT_EQUAL_INT(
			 "result",
			 result,
			 -1 );

			EVT_TEST_ASSERT_IS_NULL(
			 "message_string",
			 message_string );

			EVT_TEST_ASSERT_IS_NOT_NULL(
			 "error",
