 * Returns 1 if successful or 0 if not
 */
int evt_test_tools_value_format(
     void )
{
	libcerror_error_t *error   = NULL;
	system_character_t *string = NULL;
	size_t string_size         = 0;
	int result                 = 0;

	EVT_TEST_RUN_WITH_ARGS(
	 "value_format: string",
	 evt_test_tools_value_format_case,
	 _SYSTEM_STRING( "" ),
	 _SYSTEM_STRING( "alpha" ),
	 _SYSTEM_STRING( "alpha" ) );

	EVT_TEST_RUN_WITH_ARGS(
	 "value_format: signed decimal",
	 evt_test_tools_value_format_case,
	 _SYSTEM_STRING( "d" ),
	 _SYSTEM_STRING( "-42" ),
	 _SYSTEM_STRING( "-42" ) );

	EVT_TEST_RUN_WITH_ARGS(
	 "value_format: I64 decimal",
	 evt_test_tools_value_format_case,
	 _SYSTEM_STRING( "I64d" ),
	 _SYSTEM_STRING( "1234567890123" ),
	 _SYSTEM_STRING( "1234567890123" ) );

	EVT_TEST_RUN_WITH_ARGS(
	 "value_format: zero padded hex",
	 evt_test_tools_value_format_case,
	 _SYSTEM_STRING( "#08x" ),
	 _SYSTEM_STRING( "255" ),
	 _SYSTEM_STRING( "0x0000ff" ) );

	EVT_TEST_RUN_WITH_ARGS(
	 "value_format: uppercase hex",
	 evt_test_tools_value_format_case,
	 _SYSTEM_STRING( "X" ),
	 _SYSTEM_STRING( "48879" ),
	 _SYSTEM_STRING( "BEEF" ) );

	EVT_TEST_RUN_WITH_ARGS(
	 "value_format: octal",
	 evt_test_tools_value_format_case,
	 _SYSTEM_STRING( "#o" ),
	 _SYSTEM_STRING( "8" ),
	 _SYSTEM_STRING( "010" ) );

	EVT_TEST_RUN_WITH_ARGS(
	 "value_format: unsigned decimal",
	 evt_test_tools_value_format_case,
	 _SYSTEM_STRING( "u" ),
	 _SYSTEM_STRING( "-1" ),
	 _SYSTEM_STRING( "18446744073709551615" ) );

	EVT_TEST_RUN_WITH_ARGS(
	 "value_format: precision",
	 evt_test_tools_value_format_case,
	 _SYSTEM_STRING( ".3s" ),
	 _SYSTEM_STRING( "alpha" ),
	 _SYSTEM_STRING( "alp" ) );

	EVT_TEST_RUN_WITH_ARGS(
	 "value_format: left aligned",
	 evt_test_tools_value_format_case,
	 _SYSTEM_STRING( "-8s" ),
	 _SYSTEM_STRING( "alpha" ),
	 _SYSTEM_STRING( "alpha   " ) );

	EVT_TEST_RUN_WITH_ARGS(
	 "value_format: integer precision",
	 evt_test_tools_value_format_case,
	 _SYSTEM_STRING( "04d" ),
	 _SYSTEM_STRING( "7" ),
	 _SYSTEM_STRING( "0007" ) );

	EVT_TEST_RUN_WITH_ARGS(
	 "value_format: float",
	 evt_test_tools_value_format_case,
	 _SYSTEM_STRING( ".2f" ),
	 _SYSTEM_STRING( "3.14159" ),
	 _SYSTEM_STRING( "3.14" ) );

	EVT_TEST_RUN_WITH_ARGS(
	 "value_format: unsupported format",
	 evt_test_tools_value_format_case,
	 _SYSTEM_STRING( "q" ),
	 _SYSTEM_STRING( "raw" ),
	 _SYSTEM_STRING( "raw" ) );

	result = evttools_value_format_allocate(
	          NULL,
	          0,
	          _SYSTEM_STRING( "value" ),
	          5,
	          &string,
	          &string_size,
	          &error );

	EVT_TEST_ASSERT_EQUAL_INT(
	 "result",
	 result,
	 -1 );

	EVT_TEST_ASSERT_IS_NOT_NULL(
	 "error",
	 error );

	libcerror_error_free(
	 &error );

	result = evttools_value_format_allocate(
	          _SYSTEM_STRING( "s" ),
	          1,
	          NULL,
	          0,
	          &string,
	          &string_size,
	          &error );

	EVT_TEST_ASSERT_EQUAL_INT(
	 "result",
	 result,
	 -1 );

	EVT_TEST_ASSERT_IS_NOT_NULL(
	 "error",
	 error );

	libcerror_error_free(
	 &error );

	string = (system_character_t *) 0x12345678UL;

	result = evttools_value_format_allocate(
	          _SYSTEM_STRING( "s" ),
	          1,
	          _SYSTEM_STRING( "value" ),
	          5,
	          &string,
	          &string_size,
	          &error );

	string = NULL;

	EVT_TEST_ASSERT_EQUAL_INT(
	 "result",
	 result,
	 -1 );

	EVT_TEST_ASSERT_IS_NOT_NULL(
	 "error",
	 error );

	libcerror_error_free(
	 &error );

	result = evttools_value_format_allocate(
